import sys

def main():
    data = sys.stdin.read().split()
    path = data[0].lower()
    m = int(data[1])
    words = data[2:2 + m]
    n = len(path)
    tbl = {}
    for c in range(26):
        ch = chr(97 + c)
        arr = [n + 1] * (n + 1)
        for i in range(n - 1, -1, -1):
            arr[i] = i + 1 if path[i] == ch else arr[i + 1]
        tbl[ch] = arr
    best = ''
    for w in words:
        w = w.lower()
        lw = len(w)
        if lw > n or lw < len(best) or (lw == len(best) and w >= best):
            continue
        pos = 0
        for ch in w:
            pos = tbl[ch][pos]
            if pos > n:
                break
        else:
            best = w
    print(best if best else '-1')

